def aggregate_label(records, label):
    if not isinstance(records, str):
        raise TypeError("records must be a string")
    if not isinstance(label, str):
        raise TypeError("label must be a string")
    if not label:
        raise ValueError("label must not be empty")
    if records == "":
        return 0

    total = 0
    for line in records.splitlines():
        if not line.strip():
            raise ValueError("blank records are not allowed")
        parts = [part.strip() for part in line.split(",")]
        if len(parts) != 3 or not parts[0] or not parts[1]:
            raise ValueError("malformed record")
        quantity_text = parts[2]
        if not quantity_text or not quantity_text.isascii() or not quantity_text.isdecimal():
            raise ValueError("quantity must be an ASCII decimal integer")
        quantity = int(quantity_text)
        if quantity >= 1_000_000:
            raise ValueError("quantity is out of range")
        if parts[0] == label:
            total += quantity
    return total

